// src/StudentDashboard.js
import React from "react";
import { useAuth } from "./auth";
import { useNavigate } from "react-router-dom";

export default function StudentDashboard() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold">Welcome{user ? `, ${user.username}` : ""}</h1>
        <div className="flex gap-3">
          <button onClick={() => navigate("/new")} className="px-4 py-2 bg-indigo-600 text-white rounded-lg">New Entry</button>
          <button onClick={() => { logout(); navigate("/login"); }} className="px-4 py-2 border rounded-lg">Logout</button>
        </div>
      </div>

      {/* stats + recent entries (use your earlier implementation) */}
      {/* ... */}
    </div>
  );
}
